preConditionHook:
// BandHighThenMidlineRetrace (Brian's phone notes P10; a kept twist).
// upT is the most recent bar in 1 .. maxWaitBars that made a highBars-bar high
// (its high is the highest of the highBars bars ENDING at it, inclusive '='
// convention) AND whose high touched the upper band. The retracement level
// is avg - retraceDevs x sd (retraceDevs 0 = the middle band, = numDevs the
// lower band), each bar against its OWN band. No bar since upT
// (1 .. upT - 1) has reached its level; this bar's low does: long, once.
// Short mirrors: a highBars-bar low touching the lower band, and this bar's
// high reaching avg + retraceDevs x sd.
// The bands are BollingerBandCross's construction, open-coded at each offset
// ii so a past bar's band is computed from price as it stood on that bar (EL's
// BollingerBand is fresh per bar; reading a stored band variable at [ii]
// would compare against its zero fill during warm-up): Average(close, length)
// summed NEWEST-FIRST, POPULATION StdDev, upper = avg + numDevs x sd, lower =
// avg + (-numDevs) x sd. `bollingerband` VERIFIED; do not reorder the loops.
upT = 0;
dnT = 0;
longHit = false;
shortHit = false;
longLevel0 = 0.0;
shortLevel0 = 0.0;
for (int ii = 0; ii <= (int)maxWaitBars; ++ii) {
    bbAvg = 0.0;
    for (int jj = 0; jj < (int)length; ++jj) {
        bbAvg += close[ii + jj];
    }
    bbAvg /= (int)length;
    bbSd = 0.0;
    for (int jj = 0; jj < (int)length; ++jj) {
        bbDev = close[ii + jj] - bbAvg;
        bbSd += bbDev * bbDev;
    }
    bbSd = std::sqrt(bbSd / (int)length);
    upperBand = bbAvg + numDevs * bbSd;
    lowerBand = bbAvg + (-numDevs) * bbSd;
    longLevel = bbAvg - retraceDevs * bbSd;
    shortLevel = bbAvg + retraceDevs * bbSd;
    if (ii == 0) {
        longLevel0 = longLevel;
        shortLevel0 = shortLevel;
    } else {
        // Highest/Lowest(.., highBars)[ii] open-coded as EL's Extremes.
        windowHigh = high[ii];
        windowLow = low[ii];
        for (int jj = 1; jj <= (int)highBars - 1; ++jj) {
            if (el_gt(high[ii + jj], windowHigh)) windowHigh = high[ii + jj];
            if (el_lt(low[ii + jj], windowLow)) windowLow = low[ii + jj];
        }
        // Walking back, a bar is checked against the level only until the
        // setup bar is found; the setup bar itself is not.
        if (upT == 0) {
            if (el_ge(high[ii], windowHigh) && el_ge(high[ii], upperBand)) upT = ii;
            else if (el_le(low[ii], longLevel)) longHit = true;
        }
        if (dnT == 0) {
            if (el_le(low[ii], windowLow) && el_le(low[ii], lowerBand)) dnT = ii;
            else if (el_ge(high[ii], shortLevel)) shortHit = true;
        }
    }
}
longSetup = upT > 0 && !longHit;
shortSetup = dnT > 0 && !shortHit;
